# ---------------------------------------------------------------- ILO Refined Global Index of Occupational Exposure to GenAI
row(slug="ilo-genai-exposure-index", name="Generative AI and Jobs: A Refined Global Index of Occupational Exposure", aka=["ILO Working Paper 140", "Global Index of Occupational Exposure to Generative AI", "Generative AI and jobs: A 2025 update", "AI impact on jobs"],
    url="https://webapps.ilo.org/static/english/intserv/working-papers/wp140/index.html", operator="International Labour Organization (ILO), with NASK and the Polish Ministry of Family, Labour and Social Policy (expert group); authors Paweł Gmyrek, Janine Berg, Karol Kamiński, Filip Konopczyński, Agnieszka Ładna, Balint Nafradi, Konrad Rosłaniec, Marek Troszyński",
    kind="index of occupational exposure, published as a working paper with a research brief",
    intersections=["gains-and-losses"],
    evidence_kind=["exposure estimate"],
    unit="a task's automation score, aggregated to a 4-digit ISCO-08 occupation (mean and standard deviation) and placed in one of four exposure gradients; employment shares then estimated by country income group, region and sex",
    labor_object="the tasks of occupations in ISCO-08 and in Poland's 6-digit classification (29,753 tasks in 2,541 occupations), and the global employment in the 112 occupations classed as exposed",
    direction={"supplies": "not recorded; the index scores tasks' technical feasibility for GenAI automation. Its scores were supplied by 1,640 people employed in Poland, each scoring tasks of their own 1-digit occupational group, and by an expert group",
               "directs": "not recorded",
               "gains": "not recorded as observed outcomes; it estimates employment shares exposed, by sex and income group, and states that the productivity benefits depend on complementing human expertise"},
    method="LLM-generated task scores (GPT-4, GPT-4o, Gemini Flash 1.5), a survey of workers scoring a representative task sample (52,558 data points on 2,861 tasks), expert validation with Delphi-style rounds, then an AI predictor fed the human scores to score all tasks; employment shares from the ILO's global estimation model on harmonised labour force microdata",
    coverage={"geography": "global, with regional and income-group estimates; the task survey run in Poland", "period": "a static snapshot of exposure at the start of 2025; published 20 May 2025"},
    count={"value": "29,753 Polish 6-digit tasks scored; 3,265 ISCO-08 tasks rescored; 1,640 survey respondents; 52,558 data points; 112 occupations classed as exposed", "as_of": "2025-05-20"},
    findings=["one in four workers globally (24%) is in an occupation with some GenAI exposure",
              "3.3% of global employment falls in the highest exposure gradient (4.7% of female, 2.4% of male employment); in high-income countries 9.6% female and 3.5% male",
              "exposed employment is 34% in high-income countries and 11% in low-income countries",
              "clerical occupations continue to have the highest exposure; some digitised professional and technical occupations increased",
              "mean automation score 0.29 in 2025 against 0.30 in 2023, with standard deviation 0.14 against 0.30",
              "most jobs are more likely to be transformed than made redundant, because of the continued need for human input"],
    stated_limits=["the estimates measure exposure and give an upper threshold; they are not the actual impact on employment",
                   "they do not account for new jobs created or future technical advances: a static snapshot at the start of 2025",
                   "the survey sample may not represent the entire working population; opinions are comparable only within each 1-digit group",
                   "for 91.5% of tasks, respondents did not report performing a similar task in their work",
                   "the index is generic, because of the nature of ISCO-08"],
    answers=["which occupations have tasks scored as technically feasible for GenAI automation, and how consistently across their tasks",
             "what share of employment sits in exposed occupations, by sex, region and country income group"],
    does_not_answer=["observed employment, wage or hours change in any occupation",
                     "whether exposure leads to job loss, transformation or new work",
                     "who directs adoption or receives the gains from it",
                     "how GenAI is in fact used at work"],
    lv_intersection="The index estimates where task labor could pass to a GenAI system on grounds of technical feasibility, task by task; it meets task-origin only as a prior on which tasks are exposed. It observes no performed work, so it cannot speak to whether a system's labor advanced a commissioned task, or to user labor drag.",
    data_access="the working paper and brief online; task-level scores published at pgmyrek.github.io/2025_GenAI_scores_ISCO08; interactive charts on the ILO site", license="CC BY 4.0 (the working paper)",
    lifecycle={"state": "active", "detail": "published 20 May 2025, updating the ILO's 2023 index; the Observatory still links its data ('AI impact on jobs') on 2026-10-29"}, founded="2023 (the first ILO index, Gmyrek, Berg and Bescond); this refinement 2025-05-20",
    version_and_time={"first_index": "2023", "wp140": "2025-05-20", "doi": "10.54394/HETP0387", "isbn": "9789220421871", "read": "2026-10-29"},
    negative_tags=["NOT an observed employment outcome", "NOT a forecast of job loss: exposure is an upper threshold of potential", "NOT a measure of AI use at work", "the worker survey was run in Poland only"],
    evidence={
      "self_description": Q("ilo-genai-exposure-index--wp140", "This study updates the ILO’s 2023 Global Index of Occupational Exposure to Generative AI (GenAI), incorporating recent advances in the technology and increasing user familiarity with GenAI tools."),
      "method": Q("ilo-genai-exposure-index--wp140", "Using a representative sample from the 29,753 tasks in the Polish occupational classification system and a survey of 1,640 people employed in each 1-digit ISCO-08 groups, we collect 52,558 data points regarding perceive potential of automation for 2,861 tasks."),
      "method_2": Q("ilo-genai-exposure-index--wp140", "We then compare this input with a survey and several rounds of Delphi-style discussions among a smaller group of international experts."),
      "method_llm": Q("ilo-genai-exposure-index--wp140", "relying on three advanced LLMs available on the market at the end of 2024: GPT-4, GPT-4o and Gemini Flash 1.5."),
      "method_predictor": Q("ilo-genai-exposure-index--wp140", "Using this approach, we generate predictions for all 29,753 tasks in the Polish classification system (Table 1)."),
      "method_isco": Q("ilo-genai-exposure-index--wp140", "we use the same system to predict automation scores for 3,265 tasks in ISCO-08"),
      "survey_design": Q("ilo-genai-exposure-index--wp140", "This means that tasks of managers are assessed by individuals working as managers, tasks of professionals are assessed by professionals, etc."),
      "occupations": Q("ilo-genai-exposure-index--wp140", "At the most detailed, 6-digit level, this framework contains 2541 occupations and 29,753 corresponding tasks (Table 1)."),
      "unit": Q("ilo-genai-exposure-index--wp140", "we rely on two moments of distribution: occupational mean and standard deviation (SD) of task-level scores pertaining to a given 4-digit occupation."),
      "exposed_occupations": Q("ilo-genai-exposure-index--wp140", "we focus on the 112 occupations identified as exposed and estimate the share of employment that these occupations represent at the global, regional, and income-based levels."),
      "employment_model": Q("ilo-genai-exposure-index--wp140", "This model is based on a harmonized microdata collection and a hierarchical imputation process"),
      "finding_global": Q("ilo-genai-exposure-index--wp140", "Globally, one in four workers are in an occupation with some GenAI exposure. 3.3% of global employment falls into the highest exposure category, albeit with significant differences between female (4.7%) and male employment (2.4%)."),
      "finding_income": Q("ilo-genai-exposure-index--wp140", "These differences increase with countries’ income (9.6% female vs 3.5% male in Gradient 4 in HICs), and so does the overall exposure (11% of total employment in LICs vs 34% in HICs)."),
      "finding_24": Q("ilo-genai-exposure-index--wp140", "one in four jobs globally (24%) has some degree of exposure, and one in three jobs in high-income countries."),
      "finding_clerical": Q("ilo-genai-exposure-index--wp140", "Clerical occupations continue to have the highest exposure levels. Additionally, some strongly digitized occupations have increased exposure"),
      "finding_scores": Q("ilo-genai-exposure-index--brief", "Overall, the automation scores are slightly lower than in 2023 (a mean automation score of 0.29 in 2025 versus 0.30 in 2023), though the variability of scores is considerably lower (standard deviation 0.14 in 2025 v. 0.30 in 2023)."),
      "finding_transformed": Q("ilo-genai-exposure-index--brief", "One in four workers across the world are in an occupation with some degree of GenAI exposure, but because of the continued need for human input, most jobs will be transformed rather than made redundant."),
      "gains": Q("ilo-genai-exposure-index--wp140", "the key to unlocking the productivity benefits of GenAI lies not in the search of outright labour savings, but in the extent to which human expertise can be complemented with new technological capacities to reshape occupations and generate additional value-added"),
      "limit": Q("ilo-genai-exposure-index--wp140", "It is important to stress that these new estimates reflect “exposure” to GenAI and not the actual impact on employment. As in 2023, the 2025 estimates represent the upper threshold of the percentage of employment that could be affected if GenAI technology were fully implemented."),
      "limit_2": Q("ilo-genai-exposure-index--wp140", "Finally, the estimates do not account for new jobs that may be created, nor the technological advances that could potentially automate more tasks in the future. In that sense, our estimates present a static snapshot of the exposure of existing occupations to GenAI at the start of 2025."),
      "limit_3": Q("ilo-genai-exposure-index--wp140", "On the downside, this survey design means that the sample may not represent the entire working population, and interpretability of opinions on the automation potential is limited to comparisons within each 1-digit group."),
      "limit_4": Q("ilo-genai-exposure-index--wp140", "For 91.5% of the tasks, respondents did not report performing a similar task in their work"),
      "limit_5": Q("ilo-genai-exposure-index--wp140", "The new global index presented in this paper is generic, due to the nature of ISCO-08 and the structure of tasks associated with occupations in this framework."),
      "limit_6": Q("ilo-genai-exposure-index--wp140", "we stress that such exposure does not imply the immediate automation of an entire occupation, but rather the potential for a large share of its current tasks to be performed using this technology."),
      "experts": Q("ilo-genai-exposure-index--wp140", "The expert group includes international specialists at the ILO and its partner organizations, NASK and the Polish Ministry of Family, Labour and Social Policy."),
      "data_access": Q("ilo-genai-exposure-index--wp140", "In addition, we make all task-level scores publicly available"),
      "data_access_2": Q("ilo-genai-exposure-index--wp140", "task-level scores within the overall hierarchy of ISCO-08 are available here:"),
      "license": Q("ilo-genai-exposure-index--wp140", "Attribution 4.0 International (CC BY 4.0)"),
      "copyright": Q("ilo-genai-exposure-index--wp140", "© International Labour Organization 2025"),
      "doi": Q("ilo-genai-exposure-index--wp140", "https://doi.org/10.54394/HETP0387"),
      "isbn": Q("ilo-genai-exposure-index--wp140", "9789220421871"),
      "date": Q("ilo-genai-exposure-index--brief", "Publication | 20 May 2025"),
      "brief": Q("ilo-genai-exposure-index--brief", "This brief summarizes an ILO Working paper that refines the global assessment of occupational exposure to generative AI."),
      "first_index": Q("ilo-genai-exposure-index--wp140", "(Gmyrek, Berg and Bescond, 2023 - GBB hereafter)"),
      "observatory": Q("ilo-platform-policy-tracker--observatory", "ILO researchers developed a methodology to estimate the effects of generative AI on existing occupations."),
    },
    relations=[{"rel": "neighbour", "target": "ilo-platform-policy-tracker", "note": "both are featured on the ILO Observatory on AI and Work in the Digital Economy"}],
    unchecked=["the task-level scores on GitHub Pages and the occupation table (Annex A1) as data", "the interactive charts", "the later ILO works listed on the Observatory (Working Paper 166, March 2026; the research brief on exposure indicators, April 2026) and whether they revise this index", "the 2023 index itself"])
